definition.css:
.d-etabs-demo{display:grid;place-items:center;position:relative;color:#f1f1f1;font-family:Inter,system-ui,sans-serif}
.d-etabs-demo-tabs{position:relative;display:grid;grid-template-columns:62px 68px 53px 69px;width:260px;height:40px;padding:3px;border:1px solid #ffffff0f;border-radius:12px;background:#171717;transform:translateY(2px);isolation:isolate}
.d-etabs-demo-tabs>button{position:relative;z-index:1;min-width:0;padding:0;border:0;border-radius:9px;background:transparent;color:#949494;font:500 13px/18px Inter,system-ui,sans-serif;cursor:pointer;transition:color var(--dur-fast) var(--ease-out)}
.d-etabs-demo-tabs>button[aria-selected="true"]{color:#f1f1f1}
.d-etabs-demo-tabs>button:focus-visible{outline:2px solid var(--focus-ring);outline-offset:2px}
.d-etabs-demo-indicator{position:absolute;left:3px;top:3px;height:32px;width:var(--width,62px);border-radius:9px;background:#272727;box-shadow:0 8px 20px #0003,0 1px 2px #0002,inset 0 1px #ffffff0f;transform:translateX(calc(var(--x,0)*1px)) scaleX(var(--sx,1)) scaleY(var(--sy,1));transform-origin:center}
.d-etabs-demo-status{position:absolute;left:50%;top:50%;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;font-size:13px}
.d-etabs-demo[data-theme="light"] .d-etabs-demo-tabs{background:#eaeaea;border-color:#00000010}.d-etabs-demo[data-theme="light"] .d-etabs-demo-indicator{background:#fff;box-shadow:0 2px 8px #0002}.d-etabs-demo[data-theme="light"] button{color:#666}.d-etabs-demo[data-theme="light"] button[aria-selected="true"]{color:#151515}
@media(prefers-reduced-motion:reduce){.d-etabs-demo-tabs>button{transition-duration:var(--dur-quick)}}

