const rail=root.querySelector('.d-etabs-demo-tabs'),indicator=root.querySelector('.d-etabs-demo-indicator'),tabs=[...rail.querySelectorAll('button')],status=root.querySelector('.d-etabs-demo-status');
let active=ctx.mode==='thumb'?1:0,x=0,target=0,v=0,running=false,frames=0,moves=0,settles=0,raf=0,auto=0,width=62,targetWidth=62,poster=ctx.mode==='thumb',last=0,accumulator=0;
function geometry(index){return tabs[index].offsetLeft-3;}
function paint(source){const stretch=ctx.reducedMotion?0:Math.min(.42,Math.abs(v)*.018);indicator.style.setProperty('--x',x.toFixed(2));indicator.style.setProperty('--width',width+'px');indicator.style.setProperty('--sx',(1+stretch).toFixed(3));indicator.style.setProperty('--sy',(1-stretch*.46).toFixed(3));Object.assign(root.dataset,{active:String(active),x:x.toFixed(2),target:target.toFixed(2),velocity:v.toFixed(3),stretch:stretch.toFixed(3),running:String(running),frames:String(frames),moves:String(moves),settles:String(settles),source});}
function loop(now){if(!running)return;const step=1000/60;accumulator+=last?Math.min(64,now-last):step;last=now;while(accumulator>=step&&running){accumulator-=step;v=(v+(target-x)*.14)*.72;x+=v;width+=(targetWidth-width)*.18;frames++;if(Math.abs(target-x)<.08&&Math.abs(v)<.04&&Math.abs(targetWidth-width)<.08){x=target;width=targetWidth;v=0;running=false;settles++;}}paint(running?'frame':'settle');if(running)raf=requestAnimationFrame(loop);}
function select(index,source,focus=false){active=(index+tabs.length)%tabs.length;target=geometry(active);targetWidth=tabs[active].offsetWidth;poster=false;moves++;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===active));tab.tabIndex=i===active?0:-1;});cancelAnimationFrame(raf);last=0;if(ctx.reducedMotion){x=target;width=targetWidth;v=0;running=false;settles++;}else{running=true;raf=requestAnimationFrame(loop);}paint(source);if(focus)tabs[active].focus();status.textContent=tabs[active].textContent+' selected';ctx.emit('change',{index:active,title:tabs[active].textContent});}
function stopAuto(){clearInterval(auto);auto=0;}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>{stopAuto();select(i,'click');});tab.addEventListener('keydown',event=>{const key=event.key;if(!['ArrowRight','ArrowLeft','Home','End'].includes(key))return;event.preventDefault();stopAuto();select(key==='Home'?0:key==='End'?3:active+(key==='ArrowRight'?1:-1),'keyboard',true);});});
function reset(){stopAuto();cancelAnimationFrame(raf);active=ctx.mode==='thumb'?1:0;poster=ctx.mode==='thumb';x=target=geometry(active);width=targetWidth=poster?112:tabs[active].offsetWidth;v=0;running=false;frames=moves=settles=0;last=accumulator=0;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===active));tab.tabIndex=i===active?0:-1;});paint('reset');status.textContent=tabs[active].textContent+' selected';}
const observer=new ResizeObserver(()=>{x=target=geometry(active);width=targetWidth=poster?112:tabs[active].offsetWidth;paint('resize');});observer.observe(rail);root.dataset.theme=ctx.theme;reset();
ctx.onAction('next',()=>{stopAuto();select(active+1,'dock');});ctx.onAction('replay',reset);
if(ctx.mode==='thumb'&&!ctx.reducedMotion)auto=setInterval(()=>select(active+1,'ambient'),2600);
return ()=>{stopAuto();cancelAnimationFrame(raf);observer.disconnect();};
